    protected void insertOrderHeader(PurchPurchaseOrderHeader _purchaseOrderHeader)
    {
        PurchTable purchTable = PurchTable::find(_purchaseOrderHeader.PurchId);

        // Should pick up details from journal, not from PO.

        str docNum = _purchaseOrderHeader.PurchOrderDocNum;

        _purchaseOrderHeader.METVersionText             = strFmt("Version %1", substr(docNum, strFind(docNum, '-', 1, 999) + 1, 999));

        if(purchTable.OrderAccount != purchTable.InvoiceAccount)
        {
            _purchaseOrderHeader.METOrderToDetails          = strFmt("ABN %1\nVendor number / Sub: %2/%3",
                purchTable.vendTable_OrderAccount().VATNum,
                purchTable.InvoiceAccount,
                purchTable.OrderAccount);
        }
        else
        {
            _purchaseOrderHeader.METOrderToDetails          = strFmt("ABN %1\nVendor number: %2",
                purchTable.vendTable_OrderAccount().VATNum,
                purchTable.OrderAccount);        
        }

        _purchaseOrderHeader.METDeliveryDate            = purchTable.DeliveryDate;
        _purchaseOrderHeader.METSpecialInstructions     = '-Special instructions-'; // tbd
        _purchaseOrderHeader.METContactName             = purchTable.editContactPersonName(false, '');
        _purchaseOrderHeader.METContactEmail            = purchTable.contactPerson().email();
        _purchaseOrderHeader.METContactPhone            = purchTable.contactPerson().phone();
        _purchaseOrderHeader.METReceivingDockDetails    = '0450999999'; // *** tbd - additional config against warehouse for dock phone? Potentially a site level.
        _purchaseOrderHeader.METLegendText              = vendFormletterParameters::find().METPurchOrderReportLegendText;

        next insertOrderHeader(_purchaseOrderHeader);
    }

    protected void insertOrderLine(PurchPurchaseOrderTmp _purchaseOrderTmp)
    {
        PurchLine purchLine = PurchLine::findInventTransId(_purchaseOrderTmp.PurchLineInventTransId);

        _purchaseOrderTmp.METGTIN                   = '[gtin]';
        _purchaseOrderTmp.METTi                     = 999;
        _purchaseOrderTmp.METHi                     = 999;
        _purchaseOrderTmp.METMLOR                   = 999;
        _purchaseOrderTmp.METPalletQty              = 999;
        _purchaseOrderTmp.METAmountIncTax           = _purchaseOrderTmp.LineAmount * 1.1; // **** todo calc tax per line
        _purchaseOrderTmp.METPurchPriceIncTax       = _purchaseOrderTmp.PurchPrice * 1.1; // **** todo calc tax per line

        next insertOrderLine(_purchaseOrderTmp);
    }
